<!DOCTYPE html>\n<html>\n<head>\n    <title>Live Maps - nMon</title>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    \n    <!-- Leaflet CSS -->\n    <link rel=\"stylesheet\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\" integrity=\"sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=\" crossorigin=\"\" />\n    \n    <style>\n        #map {\n            height: 600px;\n            width: 100%;\n            border-radius: 6px;\n            box-shadow: 0 2px 8px rgba(0,0,0,0.1);\n        }\n        \n        .map-container {\n            padding: 20px;\n        }\n        \n        .map-stats {\n            display: flex;\n            gap: 20px;\n            margin-bottom: 20px;\n            flex-wrap: wrap;\n        }\n        \n        .stat-card {\n            background: white;\n            border-radius: 6px;\n            padding: 15px 20px;\n            box-shadow: 0 2px 8px rgba(0,0,0,0.1);\n            flex: 1;\n            min-width: 150px;\n        }\n        \n        .stat-card h3 {\n            margin: 0 0 5px 0;\n            font-size: 24px;\n            font-weight: 600;\n        }\n        \n        .stat-card p {\n            margin: 0;\n            color: #666;\n            font-size: 14px;\n        }\n        \n        .stat-card.online h3 { color: #28a745; }\n        .stat-card.warning h3 { color: #ffc107; }\n        .stat-card.critical h3 { color: #dc3545; }\n        .stat-card.offline h3 { color: #6c757d; }\n        \n        .legend {\n            background: white;\n            padding: 10px 15px;\n            border-radius: 6px;\n            box-shadow: 0 2px 8px rgba(0,0,0,0.1);\n            display: flex;\n            gap: 15px;\n            flex-wrap: wrap;\n        }\n        \n        .legend-item {\n            display: flex;\n            align-items: center;\n            gap: 5px;\n        }\n        \n        .legend-dot {\n            width: 12px;\n            height: 12px;\n            border-radius: 50%;\n        }\n        \n        .legend-dot.online { background: #28a745; }\n        .legend-dot.warning { background: #ffc107; }\n        .legend-dot.critical { background: #dc3545; }\n        .legend-dot.offline { background: #6c757d; }\n        \n        .agent-popup {\n            min-width: 200px;\n        }\n        \n        .agent-popup h4 {\n            margin: 0 0 10px 0;\n            font-size: 16px;\n            border-bottom: 1px solid #eee;\n            padding-bottom: 8px;\n        }\n        \n        .agent-popup .info-row {\n            display: flex;\n            justify-content: space-between;\n            margin-bottom: 5px;\n            font-size: 13px;\n        }\n        \n        .agent-popup .label {\n            color: #666;\n        }\n        \n        .agent-popup .value {\n            font-weight: 500;\n        }\n        \n        .agent-popup .status-badge {\n            display: inline-block;\n            padding: 2px 8px;\n            border-radius: 4px;\n            font-size: 12px;\n            color: white;\n        }\n        \n        .status-badge.online { background: #28a745; }\n        .status-badge.warning { background: #ffc107; color: #333; }\n        .status-badge.critical { background: #dc3545; }\n        .status-badge.offline { background: #6c757d; }\n        \n        .btn-action {\n            margin-top: 10px;\n            width: 100%;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"map-container\">\n        <div class=\"map-stats\">\n            <div class=\"stat-card online\">\n                <h3 id=\"online-count\">0</h3>\n                <p>Online</p>\n            </div>\n            <div class=\"stat-card warning\">\n                <h3 id=\"warning-count\">0</h3>\n                <p>Warning</p>\n            </div>\n            <div class=\"stat-card critical\">\n                <h3 id=\"critical-count\">0</h3>\n                <p>Critical</p>\n            </div>\n            <div class=\"stat-card offline\">\n                <h3 id=\"offline-count\">0</h3>\n                <p>Offline</p>\n            </div>\n        </div>\n        \n        <div id=\"map\"></div>\n        \n        <div class=\"legend\">\n            <div class=\"legend-item\">\n                <div class=\"legend-dot online\"></div>\n                <span>Online</span>\n            </div>\n            <div class=\"legend-item\">\n                <div class=\"legend-dot warning\"></div>\n                <span>Warning</span>\n            </div>\n            <div class=\"legend-item\">\n                <div class=\"legend-dot critical\"></div>\n                <span>Critical</span>\n            </div>\n            <div class=\"legend-item\">\n                <div class=\"legend-dot offline\"></div>\n                <span>Offline</span>\n            </div>\n        </div>\n    </div>\n    \n    <!-- Leaflet JS -->\n    <script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\" integrity=\"sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=\" crossorigin=\"\"></script>\n    \n    <script>\n    $(document).ready(function() {\n        // Initialize map\n        var map = L.map('map').setView([0, 0], 2);\n        \n        // Add tile layer\n        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {\n            attribution: '&copy; OpenStreetMap contributors'\n        }).addTo(map);\n        \n        // Custom markers\n        var markers = {};\n        var agentData = [];\n        \n        // Status colors\n        var statusColors = {\n            1: '#28a745',  // Online\n            2: '#ffc107',  // Warning\n            3: '#dc3545',  // Critical\n            0: '#6c757d'   // Offline\n        };\n        \n        var statusNames = {\n            1: 'Online',\n            2: 'Warning',\n            3: 'Critical',\n            0: 'Offline'\n        };\n        \n        // Load map data\n        function loadMapData() {\n            $.ajax({\n                url: '?json=map',\n                type: 'GET',\n                dataType: 'json',\n                success: function(data) {\n                    agentData = data;\n                    updateMap(data);\n                    updateStats(data);\n                },\n                error: function() {\n                    console.error('Failed to load map data');\n                }\n            });\n        }\n        \n        // Update map with agent data\n        function updateMap(data) {\n            // Clear existing markers\n            for (var id in markers) {\n                map.removeLayer(markers[id]);\n            }\n            markers = {};\n            \n            var bounds = [];\n            \n            data.forEach(function(agent) {\n                if (agent.lat && agent.lng) {\n                    // Create custom icon\n                    var color = statusColors[agent.status] || '#6c757d';\n                    \n                    var icon = L.divIcon({\n                        className: 'custom-marker',\n                        html: '<div style=\"background:' + color + '; width: 20px; height: 20px; border-radius: 50%; border: 3px solid white; box-shadow: 0 2px 6px rgba(0,0,0,0.3);\"></div>',\n                        iconSize: [20, 20],\n                        iconAnchor: [10, 10]\n                    });\n                    \n                    // Create marker\n                    var marker = L.marker([agent.lat, agent.lng], {icon: icon}).addTo(map);\n                    \n                    // Create popup content\n                    var popupContent = '<div class=\"agent-popup\">' +\n                        '<h4>' + agent.name + '</h4>' +\n                        '<div class=\"info-row\">' +\n                        '   <span class=\"label\">Status:</span>' +\n                        '   <span class=\"status-badge ' + statusNames[agent.status].toLowerCase() + '\">' + statusNames[agent.status] + '</span>' +\n                        '</div>' +\n                        '<div class=\"info-row\">' +\n                        '   <span class=\"label\">Type:</span>' +\n                        '   <span class=\"value\">' + agent.type + '</span>' +\n                        '</div>' +\n                        '<div class=\"info-row\">' +\n                        '   <span class=\"label\">Uptime:</span>' +\n                        '   <span class=\"value\">' + agent.uptime + '%</span>' +\n                        '</div>';\n                    \n                    if (agent.location_name) {\n                        popupContent += '<div class=\"info-row\">' +\n                            '   <span class=\"label\">Location:</span>' +\n                            '   <span class=\"value\">' + agent.location_name + '</span>' +\n                            '</div>';\n                    }\n                    \n                    if (agent.ip) {\n                        popupContent += '<div class=\"info-row\">' +\n                            '   <span class=\"label\">IP:</span>' +\n                            '   <span class=\"value\">' + agent.ip + '</span>' +\n                            '</div>';\n                    }\n                    \n                    popupContent += '<a href=\"?route=servers/manage-' + agent.type + '&id=' + agent.id + '\" class=\"btn btn-primary btn-action btn-sm\">View Details</a>' +\n                        '</div>';\n                    \n                    marker.bindPopup(popupContent);\n                    \n                    markers[agent.id] = marker;\n                    bounds.push([agent.lat, agent.lng]);\n                }\n            });\n            \n            // Fit map to bounds if we have agents\n            if (bounds.length > 0) {\n                map.fitBounds(bounds, {padding: [50, 50]});\n            }\n        }\n        \n        // Update statistics\n        function updateStats(data) {\n            var stats = {online: 0, warning: 0, critical: 0, offline: 0};\n            \n            data.forEach(function(agent) {\n                switch(agent.status) {\n                    case 1: stats.online++; break;\n                    case 2: stats.warning++; break;\n                    case 3: stats.critical++; break;\n                    default: stats.offline++;\n                }\n            });\n            \n            $('#online-count').text(stats.online);\n            $('#warning-count').text(stats.warning);\n            $('#critical-count').text(stats.critical);\n            $('#offline-count').text(stats.offline);\n        }\n        \n        // Auto-refresh every 30 seconds\n        setInterval(loadMapData, 30000);\n        \n        // Initial load\n        loadMapData();\n    });\n    </script>\n</body>\n</html>\n